CREATE TABLE `Staff` (`staff_id` DECIMAL(18,2), `gender` VARCHAR(100), `first_name` VARCHAR(100), `last_name` VARCHAR(100), `email_address` VARCHAR(100), `phone_number` VARCHAR(100));
CREATE TABLE `Customers` (`customer_id` DECIMAL(18,2), `customer_type_code` VARCHAR(100), `address_line_1` VARCHAR(100), `address_line_2` VARCHAR(100), `town_city` VARCHAR(100), `state` VARCHAR(100), `email_address` VARCHAR(100), `phone_number` VARCHAR(100));
CREATE TABLE `Products` (`product_id` DECIMAL(18,2), `parent_product_id` DECIMAL(18,2), `product_category_code` VARCHAR(100), `date_product_first_available` DATETIME, `date_product_discontinued` DATETIME, `product_name` VARCHAR(100), `product_description` VARCHAR(100), `product_price` DECIMAL(18,2));
CREATE TABLE `Complaints` (`complaint_id` DECIMAL(18,2), `product_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `complaint_outcome_code` VARCHAR(100), `complaint_status_code` VARCHAR(100), `complaint_type_code` VARCHAR(100), `date_complaint_raised` DATETIME, `date_complaint_closed` DATETIME, `staff_id` DECIMAL(18,2));
